(function () {
  'use strict';

  var STORAGE_KEY = 'pw-todo-items';
  var FILTER_KEY = 'pw-todo-filter';

  var input = document.getElementById('new-todo-input');
  var form = document.getElementById('new-todo-form');
  var list = document.getElementById('todo-list');
  var remainingEl = document.getElementById('remaining-count');
  var filterBtns = Array.prototype.slice.call(document.querySelectorAll('.filter-btn'));

  function load() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  function save(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function currentFilter() {
    return localStorage.getItem(FILTER_KEY) || 'all';
  }

  var todos = load();

  function render() {
    var filter = currentFilter();
    filterBtns.forEach(function (btn) {
      btn.classList.toggle('active', btn.dataset.filter === filter);
    });

    list.innerHTML = '';
    todos.forEach(function (todo, index) {
      if (filter === 'active' && todo.done) return;
      if (filter === 'completed' && !todo.done) return;

      var li = document.createElement('li');
      li.className = todo.done ? 'done' : '';
      li.dataset.index = String(index);

      var checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = todo.done;
      checkbox.addEventListener('change', function () {
        todos[index].done = checkbox.checked;
        save(todos);
        render();
      });

      var span = document.createElement('span');
      span.className = 'todo-text';
      span.textContent = todo.text;

      var del = document.createElement('button');
      del.className = 'delete-btn';
      del.textContent = 'Delete';
      del.setAttribute('aria-label', 'Delete ' + todo.text);
      del.addEventListener('click', function () {
        todos.splice(index, 1);
        save(todos);
        render();
      });

      li.appendChild(checkbox);
      li.appendChild(span);
      li.appendChild(del);
      list.appendChild(li);
    });

    var remaining = todos.filter(function (t) { return !t.done; }).length;
    remainingEl.textContent = remaining + ' item' + (remaining === 1 ? '' : 's') + ' left';
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var text = input.value.trim();
    if (!text) return;
    todos.push({ text: text, done: false });
    input.value = '';
    save(todos);
    render();
  });

  filterBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      localStorage.setItem(FILTER_KEY, btn.dataset.filter);
      render();
    });
  });

  render();
})();

