import { test, expect } from './fixtures';

const COUNT = '#remaining-count';
const INPUT = '#new-todo-input';

async function addTodo(page: import('@playwright/test').Page, text: string) {
  await page.fill(INPUT, text);
  await page.press(INPUT, 'Enter');
}

async function gotoFresh(page: import('@playwright/test').Page) {
  await page.goto('/');
  await page.evaluate(() => {
    localStorage.clear();
  });
  await page.reload();
}

test('adding three todos updates the remaining count', async ({ page }) => {
  await gotoFresh(page);
  await expect(page.locator(COUNT)).toHaveText('0 items left');

  for (const t of ['alpha', 'beta', 'gamma']) {
    await addTodo(page, t);
  }
  await expect(page.locator(COUNT)).toHaveText('3 items left');
  await expect(page.locator('#todo-list li')).toHaveCount(3);
});

test('toggling moves items between filters', async ({ page }) => {
  await gotoFresh(page);
  await addTodo(page, 'walk the dog');
  await addTodo(page, 'write report');

  // Toggle the first item to done.
  const firstItem = page.locator('#todo-list li', { hasText: 'walk the dog' });
  await firstItem.locator('input[type=checkbox]').check();
  await expect(firstItem).toHaveClass(/done/);
  await expect(page.locator(COUNT)).toHaveText('1 item left');

  await page.click('#filter-active');
  await expect(page.locator('#todo-list')).toHaveText(/write report/);
  await expect(page.locator('#todo-list')).not.toHaveText(/walk the dog/);

  await page.click('#filter-completed');
  await expect(page.locator('#todo-list')).toHaveText(/walk the dog/);
  await expect(page.locator('#todo-list')).not.toHaveText(/write report/);

  await page.click('#filter-all');
  await expect(page.locator('#todo-list li')).toHaveCount(2);

  // Toggle back to active; it should leave Completed and reappear under Active.
  await firstItem.locator('input[type=checkbox]').uncheck();
  await page.click('#filter-completed');
  await expect(page.locator('#todo-list li')).toHaveCount(0);
  await page.click('#filter-active');
  await expect(page.locator('#todo-list')).toHaveText(/walk the dog/);
  await expect(page.locator('#todo-list')).toHaveText(/write report/);
});

test('deleting a todo removes it from the list and count', async ({ page }) => {
  await gotoFresh(page);
  await addTodo(page, 'keep me');
  await addTodo(page, 'delete me');

  await page
    .locator('#todo-list li', { hasText: 'delete me' })
    .locator('.delete-btn')
    .click();

  await expect(page.locator('#todo-list')).toHaveText(/keep me/);
  await expect(page.locator('#todo-list')).not.toHaveText(/delete me/);
  await expect(page.locator('#todo-list li')).toHaveCount(1);
  await expect(page.locator(COUNT)).toHaveText('1 item left');
});

test('todos persist across page reload', async ({ page }) => {
  await gotoFresh(page);
  await addTodo(page, 'persistent task');
  await page.locator('#todo-list li', { hasText: 'persistent task' }).locator('input[type=checkbox]').check();

  await page.reload();

  await expect(page.locator('#todo-list li', { hasText: 'persistent task' })).toBeVisible();
  await expect(
    page.locator('#todo-list li', { hasText: 'persistent task' }).locator('input[type=checkbox]')
  ).toBeChecked();
  await expect(page.locator(COUNT)).toHaveText('0 items left');
});

